import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
function extract(src,name){const start=src.indexOf('function '+name+'(');assert(start>=0);const brace=src.indexOf('{',start);let n=1,i=brace+1;while(n&&i<src.length){if(src[i]==='{')n++;if(src[i]==='}')n--;i++;}return src.slice(start,i);}
const source=fs.readFileSync('games/2048/index.html','utf8'),line=vm.runInNewContext(extract(source,'line')+';line');
for(const [a,b,gain] of [[[2,2,2,2],[4,4,0,0],8],[[2,2,4,0],[4,4,0,0],4],[[4,0,4,4],[8,4,0,0],8],[[2,4,8,16],[2,4,8,16],0]]){const result=line(a);assert.deepEqual([...result[0]],b);assert.equal(result[1],gain);assert.equal(result[0].reduce((s,x)=>s+x,0),a.reduce((s,x)=>s+x,0));}
for(let n=0;n<10000;n++){const a=Array.from({length:4},()=>Math.random()<.2?0:2**(1+Math.floor(Math.random()*8)));const [b]=line(a);assert.equal(b.reduce((s,x)=>s+x,0),a.reduce((s,x)=>s+x,0));assert.equal(b.length,4);assert(b.every(x=>x===0||Number.isInteger(Math.log2(x))));}
const memory=fs.readFileSync('games/memory/index.html','utf8');for(const diff of ['4','6','8']){const ctx={data:{settings:{diff,deck:'artifact'}},itemNames:{artifact:Array.from({length:16},(_,i)=>'item'+i)},Math};vm.createContext(ctx);const deck=vm.runInContext(extract(memory,'buildDeck')+';buildDeck()',ctx);assert.equal(deck.length,Number(diff)**2);assert.equal(new Set(deck.map(x=>x.id)).size,deck.length);const counts=new Map;for(const c of deck)counts.set(c.key,(counts.get(c.key)||0)+1);assert([...counts.values()].every(x=>x%2===0));assert(deck.every(x=>!x.up&&!x.matched));}
console.log('PASS 2048 merge-once rules, scores, 10000 tile conservation cases; memory 4/6/8 boards preserve unique instance ids and even matching groups');
